// 클라이언트: 재시도해도 같은 키를 쓴다 (새 시도가 아니라 같은 시도니까)
fetch('/payments', {
  method: 'POST',
  headers: { 'Idempotency-Key': 요청id },   // 예: crypto.randomUUID()
  body: JSON.stringify(주문),
});

// 서버
async function 결제(key, body) {
  const 이전 = await store.get(key);
  if (이전) return 이전.response;             // 그대로 재생 — 다시 처리하지 않는다

  const 잠금 = await store.lock(key);         // 동시에 두 번 와도 하나만
  if (!잠금) return { status: 409, code: 'IN_PROGRESS' };

  const 결과 = await 실제결제(body);
  await store.save(key, { response: 결과, body해시: 해시(body) }, { ttl: '24h' });
  return 결과;
}
